def count_no_of_ways(n, k):
    if n == 1:
        return k  # Base case where n = 1, as there are k ways to paint the single post.
    if n == 2:
        return k * k  # Base case where n = 2, as there are k^2 ways to paint the first two posts.

    if n > 2:
        # Initialize the DP array, where dp[i] will be the number of ways to paint i posts.
        dp = [0] * n
        dp[0] = k  # Base case for the first post.
        dp[1] = k * k  # Base case for the first two posts.

        if n > 2:
            for i in range(2, n):
                # The number of ways to paint the ith post, considering that the previous one can have 2 colors the same.
                dp[i] = dp[i - 1] * (k - 1) + dp[i - 2] * k if n > 2 else k * k
    return dp[n - 1]

